def _compute_widths(self, rows: list[list[str]], options: OptionsType) -> None:
    """Calculate the width of each column in the table based on content and constraints."""
    if not self._field_names:
        return

    # Initialize widths based on field names
    self._widths = [_str_block_width(field) for field in self._field_names]

    # Update widths based on data
    for row in rows:
        for i, cell in enumerate(row):
            if i < len(self._widths):
                cell_width = max(_str_block_width(line) for line in cell.split("\n"))
                self._widths[i] = max(self._widths[i], cell_width)

    # Apply min_width constraint
    for i, field in enumerate(self._field_names):
        if field in self._min_width:
            self._widths[i] = max(self._widths[i], self._min_width[field])
        elif options["min_width"] is not None:
            if isinstance(options["min_width"], int):
                self._widths[i] = max(self._widths[i], options["min_width"])
            elif isinstance(options["min_width"], dict) and field in options["min_width"]:
                self._widths[i] = max(self._widths[i], options["min_width"][field])

    # Apply max_width constraint
    for i, field in enumerate(self._field_names):
        if field in self._max_width:
            self._widths[i] = min(self._widths[i], self._max_width[field])
        elif options["max_width"] is not None:
            if isinstance(options["max_width"], int):
                self._widths[i] = min(self._widths[i], options["max_width"])
            elif isinstance(options["max_width"], dict) and field in options["max_width"]:
                self._widths[i] = min(self._widths[i], options["max_width"][field])

    # Handle table width constraints
    if options["min_table_width"] or options["max_table_width"]:
        current_table_width = self._compute_table_width(options)

        if options["min_table_width"] and current_table_width < options["min_table_width"]:
            # Distribute extra width proportionally
            extra_width = options["min_table_width"] - current_table_width
            for i in range(len(self._widths)):
                self._widths[i] += extra_width // len(self._widths)
            # Add remaining width to first columns
            remainder = extra_width % len(self._widths)
            for i in range(remainder):
                self._widths[i] += 1

        elif options["max_table_width"] and current_table_width > options["max_table_width"]:
            # Reduce width proportionally
            excess_width = current_table_width - options["max_table_width"]
            for i in range(len(self._widths)):
                reduction = min(excess_width // len(self._widths), self._widths[i] - 1)
                self._widths[i] -= reduction
                excess_width -= reduction
            # If we still have excess width, take from the widest columns
